/* Offline governance authoring. Observations below are synthetic, never live discovery. */
(() => {
 'use strict';
 const clone=x=>JSON.parse(JSON.stringify(x)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const initial={
  agentConnections:['control','direct'].map((provider,i)=>({id:'demo-'+provider,name:i?'受控 ACP Agent B':'总控 Agent A',agentId:'demo-agent-'+provider,provider,owner:'测试平台组',address:i?'template://demo-agent-b':'https://control.example.invalid',authMode:'agent_managed',credentialRef:'',runtimeId:'demo-runtime',enabled:true,revision:1,mcpAllowed:true,quotaCapability:'unreported',observation:'synthetic',catalog:['demo-model-general','demo-model-analysis']})),
  runtimeProfiles:[{id:'demo-runtime',name:'只读隔离执行配置',nodeRef:'demo-node-1',identityRef:'demo-readonly-identity',rootRef:'workspace://demo-readonly',network:'allowlist',readOnly:true,terminal:false,enabled:true,revision:1}],
  contextPolicies:[{id:'demo-context-policy',name:'默认会话上下文',inputLimit:12000,outputReserve:4000,historyMessages:20,memory:'off',enabled:true,revision:1}]
 };
 const fingerprint=x=>JSON.stringify([x.provider,x.agentId,x.address,x.authMode,x.credentialRef,x.runtimeId,x.mcpAllowed]);
 initial.agentConnections.forEach(x=>x.observationFingerprint=fingerprint(x));
 const types={integrations:'agentConnections',runtime:'runtimeProfiles',context:'contextPolicies'};
 const chosen={integrations:'demo-control',runtime:'demo-runtime',context:'demo-context-policy'};let active='integrations',opened=false,notice='';
 const C=()=>window.ConfigurationPrototype;
 const field=(label,key,value,type='text')=>`<label class="admin-field">${label}<input data-gov-field="${key}" type="${type}" value="${esc(value)}"></label>`;
 const select=(label,key,value,options)=>`<label class="admin-field">${label}<select data-gov-field="${key}">${options.map(([id,n])=>`<option value="${id}" ${id===value?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
 const toggle=(label,key,value)=>`<label class="admin-check"><input type="checkbox" data-gov-field="${key}" ${value?'checked':''}>${label}</label>`;
 const button=(action,label,extra='')=>`<button type="button" data-gov="${action}" ${extra}>${label}</button>`;
 function current(){return C().draft()[types[active]].find(x=>x.id===chosen[active]);}
 function issues(c){const out=[],add=(type,x,field,message)=>out.push({type,id:x.id,field,message:x.name+'：'+message});
  for(const type of Object.values(types)){const names=new Set();for(const x of c[type]){if(!x.name.trim()||names.has(x.name.trim()))add(type,x,'name','名称不能为空或重复');names.add(x.name.trim());}}
  for(const a of c.agentConnections){if(!a.enabled)continue;if(!a.owner.trim()||!a.agentId.trim())add('agentConnections',a,'owner','需填写负责人和稳定 Agent 标识');if(a.provider==='direct'?!/^template:\/\/[A-Za-z0-9_./-]+$/.test(a.address):!window.ResourceDesign.validEndpoint(a.address))add('agentConnections',a,'address','需受信启动模板或无凭据 HTTPS 接入地址');if(a.authMode==='secret_ref'&&!/^secret-ref\/[A-Za-z0-9_./-]+$/.test(a.credentialRef))add('agentConnections',a,'credentialRef','需要受控凭据引用');if(!c.runtimeProfiles.some(r=>r.id===a.runtimeId&&r.enabled))add('agentConnections',a,'runtimeId','运行配置不可用');if(a.observation!=='synthetic'||a.observationFingerprint!==fingerprint(a))add('agentConnections',a,'observation','请重新模拟发现；真实能力仍未验证');}
  for(const r of c.runtimeProfiles){if(r.enabled&&(!r.nodeRef.trim()||!r.identityRef.trim()||!r.rootRef.startsWith('workspace://')||r.network!=='allowlist'||!r.readOnly||r.terminal))add('runtimeProfiles',r,'rootRef','初始范围只允许登记工作区、只读、受限网络且关闭任意终端');}
  for(const p of c.contextPolicies){if(!Number.isInteger(p.inputLimit)||p.inputLimit<1||p.inputLimit>1000000||!Number.isInteger(p.outputReserve)||p.outputReserve<1||p.outputReserve>1000000||!Number.isInteger(p.historyMessages)||p.historyMessages<0||p.historyMessages>100)add('contextPolicies',p,'inputLimit','上下文预算应为正整数，历史条数为 0–100；真实模型窗口还需复查');}
  for(const m of c.models){const a=c.agentConnections.find(a=>a.id===m.connectionId);if(m.enabled&&(!a||a.agentId!==m.agentId||a.provider!==m.provider||!a.catalog.includes(m.quotaModelId)))add('models',m,'connectionId','Agent 身份绑定不一致或模型不在该连接的合成发现清单中，请重新绑定模型预设');}
  for(const e of c.environments){if(!e.enabled)continue;const ids=e.allowedModelIds||[];if(!ids.includes(e.defaultModel))add('environments',e,'defaultModel','默认模型必须属于此环境允许的 Agent / 模型组合');if(ids.some(id=>!c.models.some(m=>m.id===id&&m.enabled)))add('environments',e,'allowedModelIds','环境绑定了已停用或不存在的模型');if(!c.contextPolicies.some(p=>p.id===e.contextPolicyId&&p.enabled))add('environments',e,'contextPolicyId','上下文策略未配置或已停用');}
  return out;
 }
 function decision(c,s){const env=c.environments.find(e=>e.id===s.environmentId),model=(s.snapshot||c).models.find(m=>m.id===s.modelId),a=c.agentConnections.find(a=>a.id===model?.connectionId),r=c.runtimeProfiles.find(r=>r.id===a?.runtimeId),p=c.contextPolicies.find(p=>p.id===env?.contextPolicyId),reasons=[];
  if(!env?.allowedModelIds?.includes(s.modelId))reasons.push('此环境未允许该 Agent / 模型组合');
  if(!a?.enabled||a.observationFingerprint!==fingerprint(a))reasons.push('Agent 连接已停用或配置变化后待重新发现');
  if(a&&(a.agentId!==model?.agentId||a.provider!==model?.provider))reasons.push('Agent 身份与模型预设不一致，不能沿用旧额度绑定');
  if(!a?.catalog.includes(model?.quotaModelId))reasons.push('模型不属于当前 Agent 的发现清单');
  if(!r?.enabled||!r.readOnly||r.terminal||r.network!=='allowlist')reasons.push('运行配置未满足只读范围');
  if(!p?.enabled)reasons.push('上下文策略不可用');
  if(env?.mcpIds?.length&&!a?.mcpAllowed)reasons.push('Agent 不支持本环境要求的受控 MCP 接入');
  return {configured:!reasons.length,reasons,connection:a?{id:a.id,revision:a.revision,agentId:a.agentId,provider:a.provider}:null,runtime:r?clone(r):null,contextPolicy:p?clone(p):null,requestedModelId:model?.quotaModelId||null,actualModelId:null,realAdmission:'unknown',realExecutionAllowed:false};
 }
 function editor(x,c){let html=field('名称','name',x.name);
  if(active==='integrations')html+=`<p class="admin-muted">① 配置连接 → ② 模拟发现 → ③ 发布模型预设 → ④ 系统环境绑定。所有结果为合成示例。</p>`+select('接入方式','provider',x.provider,[['control','总控适配器'],['direct','受控 ACP 直连']])+field('Agent 稳定标识','agentId',x.agentId)+field('负责人','owner',x.owner)+field(x.provider==='direct'?'受信启动模板（template://）':'总控 HTTPS 接入地址','address',x.address)+select('账号管理','authMode',x.authMode,[['agent_managed','Agent / 总控自行管理登录'],['secret_ref','受控宿主按凭据引用注入']])+(x.authMode==='secret_ref'?field('凭据引用（不填秘密值）','credentialRef',x.credentialRef):'<p class="admin-muted">由执行器完成登录；平台记录认证状态与责任人。原型不启动登录。</p>')+select('运行配置','runtimeId',x.runtimeId,c.runtimeProfiles.map(r=>[r.id,r.name]))+select('额度能力演练（不是实机证据）','quotaCapability',x.quotaCapability||'unreported',[['unreported','未上报：平台限制＋未知用量'],['reported','可统计：回执统计，无内部硬限制'],['enforced','可强制：合成调用前拦截示例']])+toggle('允许演示受控 MCP 接入','mcpAllowed',x.mcpAllowed)+button('discover','模拟发现 Agent 与模型')+`<p class="gov-observation">${x.observationFingerprint===fingerprint(x)?'合成发现完成':'配置待发现'} · 真实认证 / 能力未知</p><ul>${x.catalog.map(id=>`<li>${esc(id)} · 示例模型</li>`).join('')}</ul>${button('create-model','为此 Agent 创建模型预设',x.catalog.length?'':'disabled')} <a href="#admin-models">查看全部模型预设 →</a>`;
  if(active==='runtime')html+=field('执行节点引用','nodeRef',x.nodeRef)+field('执行身份引用','identityRef',x.identityRef)+field('登记工作区引用','rootRef',x.rootRef)+select('网络策略','network',x.network,[['allowlist','仅允许登记的模型和工具服务'],['unrestricted','任意网络（本阶段不准入）']])+toggle('只读代码与资源','readOnly',x.readOnly)+toggle('任意终端（本阶段不准入）','terminal',x.terminal)+`<p class="admin-muted">这是 Agent 的运行配置，不是测试 / 生产业务环境。目录与 Git 来源在系统环境中绑定；真实隔离尚未验证。</p>`;
  if(active==='context')html+=field('输入预算上限（Token）','inputLimit',x.inputLimit,'number')+field('输出预留（Token）','outputReserve',x.outputReserve,'number')+field('最近消息上限（条）','historyMessages',x.historyMessages,'number')+select('长期记忆','memory',x.memory,[['off','关闭'],['personal','经审核的个人记忆'],['environment','经审核的同环境记忆']])+`<p class="admin-muted">固定策略、系统 / 环境背景、当前问题、获准证据先进入上下文；旧消息摘要带来源，长期记忆还需审核及当前 ACL。模型窗口未知仍阻断真实发送。</p>`;
  return html+toggle('启用此配置（仅离线演示）','enabled',x.enabled);
 }
 function view(page){if(active!==page){active=page;opened=false;notice='';}const c=C().draft(),type=types[page];if(!c[type].some(x=>x.id===chosen[page]))chosen[page]=c[type][0]?.id;const x=current(),label={integrations:'Agent 连接',runtime:'运行配置',context:'上下文策略'}[page];
  return `<section id="governance-panel"><div class="admin-toolbar"><span>已应用修订 ${C().current().revision} · <span id="gov-dirty">${C().changes().length}</span> 项未应用改动</span><div>${button('discard','放弃当前草稿')}${button('publish-set','选择变更集')}${button('publish','预览并应用','class="admin-primary"')}</div></div><p id="gov-notice" role="status">${esc(notice)}</p><section class="ops-panel"><div class="ops-panel-head"><h2>${label}</h2>${button('add','＋ 新增')}</div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>名称</th><th>状态</th><th>关联情况</th><th>操作</th></tr></thead><tbody>${c[type].map(row=>`<tr><td>${esc(row.name)}</td><td>${row.enabled?'已配置 · 真实未验证':'已停用 / 草稿'}</td><td>${page==='integrations'?c.models.filter(m=>m.connectionId===row.id).length+' 个模型预设':page==='runtime'?c.agentConnections.filter(a=>a.runtimeId===row.id).length+' 条 Agent 连接':c.environments.filter(e=>e.contextPolicyId===row.id).length+' 个业务环境'}</td><td>${button('edit','配置',`data-id="${row.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>${opened&&x?`<section class="service-card gov-editor"><header><h2>${esc(x.name)}</h2>${button('close','收起配置')}</header>${editor(x,c)}</section>`:''}${page==='integrations'?'<p class="admin-note">下一步：<a href="#admin-models">发布模型预设</a> → <a href="#admin-systems">系统设置内绑定环境</a>。MCP 在<a href="#admin-resources">资源目录</a>独立登记。</p>':''}${page==='context'?memoryTable():''}<dialog id="govern-dialog" aria-labelledby="gov-title"></dialog></section>`;
 }
 function memoryTable(){const m=window.ReviewJourney.memory();return `<section class="ops-panel"><div class="ops-panel-head"><h2>记忆条目</h2><span>合成来源 · ${esc(m.scope)}</span></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>条目</th><th>状态</th><th>来源可访问</th><th>操作</th></tr></thead><tbody><tr><td>报表核对先对齐时间与状态</td><td>${esc(({candidate:'待审核',reviewed:'已审核',active:'已启用',revoked:'已撤销',deletion_pending:'删除待回执'})[m.state]||m.state)}</td><td>${m.sourceAccess?'是（合成）':'已撤权'}</td><td>${button('memory-detail','查看详情')}</td></tr></tbody></table></div><p class="admin-muted">下方“记忆详情与操作”可审核、启用、撤销和申请删除。删除等待回执，不能视为已经清除外部副本。</p></section>`;}
 function feedback(message){notice=message;const el=document.querySelector('#gov-notice');if(el)el.textContent=message;}
 function refresh(){window.ServiceDesignPrototype.render(active);}
 document.addEventListener('input',e=>{if(!e.target.dataset.govField)return;if(window.ServiceDesignPrototype.actor()!=='config'){feedback('当前角色没有接入配置权限。');refresh();return;}const x=current();x[e.target.dataset.govField]=e.target.type==='number'?(e.target.value===''?null:Number(e.target.value)):e.target.value;document.querySelector('#gov-dirty').textContent=C().changes().length;});
 document.addEventListener('change',e=>{if(!e.target.dataset.govField||e.target.tagName!=='SELECT'&&e.target.type!=='checkbox')return;if(window.ServiceDesignPrototype.actor()!=='config'){feedback('当前角色没有接入配置权限。');refresh();return;}const x=current(),f=e.target.dataset.govField;x[f]=e.target.type==='checkbox'?e.target.checked:e.target.value;refresh();});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-gov]');if(!b)return;const action=b.dataset.gov,dialog=document.querySelector('#govern-dialog');if(action==='cancel'){dialog.close();document.querySelector('[data-gov=publish]')?.focus();return;}
  if(window.ServiceDesignPrototype.actor()!=='config'){feedback('当前角色没有接入配置权限。');return;}
  if(action==='create-model'){window.AdminPrototype.createForConnection(current().id);return;}
  if(action==='memory-detail'){const d=document.querySelector('.governance-diagnostics');d.open=true;d.scrollIntoView({block:'start'});d.querySelector('summary')?.focus();return;}
  if(action==='edit'){chosen[active]=b.dataset.id;opened=true;refresh();document.querySelector('.gov-editor input')?.focus();return;}
  if(action==='close'){opened=false;refresh();document.querySelector('[data-gov=edit][data-id="'+chosen[active]+'"]')?.focus();return;}
  if(action==='add'){const type=types[active],rows=C().draft()[type],x=clone(initial[type][0]);x.id='demo-'+type+'-'+(rows.length+1);x.name='新'+({integrations:'Agent 连接',runtime:'运行配置',context:'上下文策略'})[active]+' '+(rows.length+1);x.enabled=false;x.revision=1;if(active==='integrations'){x.agentId=x.id+'-agent';x.observation='unknown';x.catalog=[];x.observationFingerprint=null;}rows.push(x);chosen[active]=x.id;opened=true;refresh();return;}
  if(action==='discover'){const x=current();x.catalog=['demo-model-general','demo-model-analysis'];x.observation='synthetic';x.observationFingerprint=fingerprint(x);notice='仅载入固定合成模型；未认证、未发起网络请求、真实能力仍未知。';refresh();return;}
  if(['publish','publish-set','discard'].includes(action)){const keys=[types[active]+':'+current().id];if(action==='publish'){const result=C().preview(keys);if(!result.ok){feedback(result.errors.join('；'));return;}}if(!C().changes().length){feedback('没有待应用的改动。');return;}dialog.innerHTML=`<h2 id="gov-title">${action==='discard'?'放弃当前对象草稿？':'应用选中的合成配置？'}</h2>${action==='discard'?'<p>其他对象的草稿保留。</p>':C().selectionFields(keys)}<p>仅实际依赖的语义变化使待确认计划失效；已有绑定不迁移。</p>${button('cancel','继续编辑')}${button(action==='discard'?'confirm-discard':'confirm','确认')}`;dialog.showModal();return;}
  if(action==='confirm'||action==='confirm-discard'){const result=action==='confirm'?C().publish(C().readSelection(dialog)):(C().discard([types[active]+':'+current().id]),{ok:true});if(!result.ok){dialog.querySelector('[data-publish-error]').textContent=result.errors.join('；');return;}notice='所选演示配置已更新；其他草稿保留，真实能力仍未知。';refresh();}
 });
 document.addEventListener('cancel',e=>{if(e.target.id==='govern-dialog')setTimeout(()=>document.querySelector('[data-gov=publish]')?.focus(),0);},true);
 window.GovernanceDesign={initial,issues,decision,view};
})();
